//! Item 5, second half: block-level functions, iterator closing, generator parameters,
//! HTML-like comments, `__proto__` in literals, mapped `arguments`, legacy octal,
//! `debugger`, numeric separators.

pub const CASES: &[(&str, &str)] = &[
    // --- function declarations in blocks (sloppy mode, Annex B.3.3)
    (r#"{ function f() { return 1 } } f()"#, "1"),
    (r#"function g() { if (true) { function inner() { return 'in' } } return inner() } g()"#, "in"),
    (r#"function g() { var t = typeof inner; { function inner() {} } return t + '|' + typeof inner } g()"#, "undefined|function"),
    (r#"function g(flag) { if (flag) { function pick() { return 'a' } } else { function pick() { return 'b' } } return pick() } g(true) + g(false)"#, "ab"),
    (r#"function g() { { function early() { return 'hoisted in block' } var r = early() } return r } g()"#, "hoisted in block"),
    (r#"function g() { 'use strict'; { function inner() {} } return typeof inner } g()"#, "undefined"),
    (r#"function g() { let inner = 1; { function inner() {} } return typeof inner } g()"#, "number"),
    (r#"function g() { { let inner = 1; { function inner() {} } } return typeof inner } g()"#, "undefined"),
    (r#"function g(p) { { function p() {} } return typeof p } g(5)"#, "number"),
    (r#"switch (1) { case 1: function sw() { return 'sw' } } sw() + '|' + typeof globalThis.sw"#, "sw|function"),
    (r#"function g() { try { function inTry() { return 't' } } catch (e) {} for (var i = 0; i < 1; i++) { function inLoop() { return 'l' } } return inTry() + inLoop() } g()"#, "tl"),
    (r#"function g() { var fs = []; for (var i = 0; i < 2; i++) { let j = i; function cap() { return j } fs.push(cap) } return fs[0]() + '|' + fs[1]() + '|' + cap() } g()"#, "0|1|1"),
    (r#"if (true) function single() { return 's' } single()"#, "s"),
    // --- for-of closes its iterator on break, return and throw
    (r#"var log = []; var it = { [Symbol.iterator]() { return { next() { return { done: false, value: 1 } }, return() { log.push('closed'); return {} } } } }; for (var v of it) { break } log.join()"#, "closed"),
    (r#"var log = []; var it = { [Symbol.iterator]() { return { next() { return { done: false, value: 1 } }, return() { log.push('closed'); return {} } } } }; try { for (var v of it) { throw new Error('x') } } catch (e) { log.push(e.message) } log.join()"#, "closed,x"),
    (r#"var log = []; var it = { [Symbol.iterator]() { return { next() { return { done: false, value: 1 } }, return() { log.push('closed'); return {} } } } }; (function () { for (var v of it) { return } })(); outer: for (var a of [1]) { for (var v of it) { continue outer } } log.join()"#, "closed,closed"),
    (r#"var log = []; var it = { [Symbol.iterator]() { var n = 0; return { next() { return { done: n++ > 2, value: n } }, return() { log.push('closed'); return {} } } } }; for (var v of it) { if (v == 1) continue; log.push(v) } log.join()"#, "2,3"),
    (r#"var log = []; var it = { [Symbol.iterator]() { return { next() { throw new Error('next failed') }, return() { log.push('closed') } } } }; try { for (var v of it) {} } catch (e) { log.push(e.message) } log.join()"#, "next failed"),
    (r#"var log = []; var it = { [Symbol.iterator]() { return { next() { return { done: false, value: 1 } }, return() { log.push('closed'); throw new Error('from return') } } } }; try { for (var v of it) { throw new Error('from body') } } catch (e) { log.push(e.message) } try { for (var v of it) { break } } catch (e) { log.push(e.message) } log.join()"#, "closed,from body,closed,from return"),
    (r#"var log = []; function* g() { try { yield 1; yield 2 } finally { log.push('fin') } } try { for (var v of g()) { throw 1 } } catch (e) { log.push('caught') } for (var v of g()) { break } log.join()"#, "fin,caught,fin"),
    (r#"var log = []; function* inner() { try { yield 1; yield 2 } finally { log.push('inner-fin') } } function* outer() { for (var v of inner()) yield v } var o = outer(); o.next(); var r = o.return(9); log.join() + '|' + r.value + '|' + r.done"#, "inner-fin|9|true"),
    (r#"var log = []; function* g() { try { yield 1; yield 2; yield 3 } finally { log.push('fin') } } function f() { for (var v of g()) { for (var w of g()) { if (w == 2) throw new Error('deep') } } } try { f() } catch (e) { log.push(e.message) } log.join()"#, "fin,fin,deep"),
    (r#"var log = []; var it = { [Symbol.iterator]() { return { next() { return { done: false, value: [1] } }, return() { log.push('closed'); return {} } } } }; for (var [a] of it) { log.push(a); break } var [first] = it; log.join()"#, "1,closed,closed"),
    (r#"var closed = 0; var it = { [Symbol.iterator]() { var n = 0; return { next() { return { done: n++ >= 3, value: n } }, return() { closed++; return {} } } } }; var sum = 0; for (var v of it) sum += v; sum + '|' + closed"#, "6|0"),
    // --- generator parameters are bound at the call
    (r#"var log = []; function* g(a = log.push('bound')) { log.push('body') } var it = g(); log.push('created'); it.next(); log.join()"#, "bound,created,body"),
    (r#"function* g(a = (() => { throw new RangeError('param') })()) {} try { g(); 'no throw' } catch (e) { e.name }"#, "RangeError"),
    (r#"function* g({ a, b } = {}, ...rest) { yield a + b + rest.length } var r = []; try { g(null) } catch (e) { r.push(e.name) } r.push(g({ a: 1, b: 2 }, 3, 4).next().value); r.join()"#, "TypeError,5"),
    (r#"function* g(a, b) { yield a + b; yield arguments.length } var it = g(1, 2, 3); [it.next().value, it.next().value, it.next().done, Object.prototype.toString.call(it)].join()"#, "3,3,true,[object Generator]"),
    (r#"var log = []; async function* g(x = log.push('bound')) { yield x } var it = g(); log.push('created'); it.next().then(r => { out = log.join() + '|' + r.value }); 0"#, "bound,created|1"),
    (r#"var n = 0; function* g(x = ++n) { yield x } var a = g(), b = g(); n + '|' + b.next().value + '|' + a.next().value"#, "2|2|1"),
    // --- HTML-like comments
    ("var x = 1; <!-- comment\nx + 1", "2"),
    ("var x = 2;\n--> comment\nx", "2"),
    ("<!-- at the very start\nvar y = 3;\n  --> indented closer\n/* block */ --> after a block comment on its own line\ny", "3"),
    ("var a = 5, b = 2; var r = a --> b; r + '|' + a", "true|4"),
    ("var x = 3; x<!--x\n", "3"),
    // --- __proto__ in object literals
    (r#"try { eval('({ __proto__: null, __proto__: null })') } catch (e) { e.name }"#, "SyntaxError"),
    (r#"try { eval('({ "__proto__": null, __proto__: {} })') } catch (e) { e.name }"#, "SyntaxError"),
    (r#"var __proto__ = 'shorthand'; var o = { __proto__: Array.prototype, ['__proto__']: 'computed' }; var s = { __proto__ }; var m = { __proto__() { return 'method' }, __proto__: null }; [o instanceof Array, Object.keys(o).join(), s.__proto__, Object.getPrototypeOf(s) === Object.prototype, typeof m.__proto__, Object.getPrototypeOf(m)].join('|')"#, "true|__proto__|shorthand|true|function|"),
    (r#"var { __proto__: a, __proto__: b } = { __proto__: { z: 1 } }; var o = { __proto__: 5 }; (a === b) + '|' + a.z + '|' + (Object.getPrototypeOf(o) === Object.prototype) + '|' + Object.keys(o).length"#, "true|1|true|0"),
    // --- arguments mapped to parameters (sloppy functions with a plain parameter list)
    (r#"function f(a, b) { arguments[0] = 'changed'; b = 'B2'; return a + '|' + arguments[1] } f('a', 'b')"#, "changed|B2"),
    (r#"function f(a) { 'use strict'; arguments[0] = 2; a = 3; return a + '|' + arguments[0] } f(1)"#, "3|2"),
    (r#"function f(a, b) { arguments[1] = 'x'; b = 'y'; return b + '|' + arguments[1] + '|' + arguments.length } f(1)"#, "y|x|1"),
    (r#"function f(a) { delete arguments[0]; arguments[0] = 'new'; a = 'param'; return a + '|' + arguments[0] } f('old')"#, "param|new"),
    (r#"function f(a = 1) { arguments[0] = 2; return a } function g(...r) { arguments[0] = 9; return r[0] } function h({ p }) { arguments[0] = null; return p } [f(5), g(1), h({ p: 'p' })].join()"#, "5,1,p"),
    (r#"function f(a, b) { var set = () => { a = 'via-closure' }; set(); var before = arguments[0]; arguments[1] = 'via-args'; return before + '|' + (() => b)() } f(1, 2)"#, "via-closure|via-args"),
    (r#"function f(a) { Object.defineProperty(arguments, '0', { value: 'dp' }); var r1 = a; Object.defineProperty(arguments, '0', { writable: false }); a = 'later'; return r1 + '|' + arguments[0] } f('x')"#, "dp|dp"),
    (r#"function f(a) { Object.defineProperty(arguments, '0', { get() { return 'getter' } }); a = 'unlinked'; return a + '|' + arguments[0] } f('x')"#, "unlinked|getter"),
    (r#"function f(x, y) { x = 9; return [].slice.call(arguments).join() + '|' + Object.keys(arguments).join() + '|' + JSON.stringify(arguments) + '|' + [...arguments].length } f(1, 2, 3)"#, "9,2,3|0,1,2|{\"0\":9,\"1\":2,\"2\":3}|3"),
    (r#"function f(a, a) { arguments[0] = 'first'; arguments[1] = 'second'; return a } function g(n) { return n > 0 ? (arguments[0]--, g(n - 1) + n) : 0 } f(1, 2) + '|' + g(3)"#, "second|2"),
    (r#"function outer(a) { function inner() { return arguments[0] } a = 'outer'; return inner('inner') + '|' + arguments[0] + '|' + (arguments.callee === outer) } outer(1)"#, "inner|outer|true"),
    // --- legacy octal, debugger, numeric separators
    (r#"[010, 0777, 08, 09.5, 0o17, 0O17, 0b11, 0xff, '\101\0\x41\7'.length, '\251' === '\xa9', '\8'].join()"#, "8,511,8,9.5,15,15,3,255,4,true,8"),
    (r#"var r = []; for (var src of ['010', '08', '"\\101"', '"\\0"', '0o10', 'function f() { "use strict"; return 010 }']) { try { r.push((0, eval)('"use strict"; ' + src)) } catch (e) { r.push(e.name) } } r.map(String).join('|')"#, "SyntaxError|SyntaxError|SyntaxError|\0|8|SyntaxError"),
    (r#"var n = 0; debugger; function f() { debugger; return ++n } if (f()) debugger; n"#, "1"),
    (r#"[1_000, 1_0.0_1, 0xFF_FF, 0b1010_1010, 0o7_7, 1e1_0].join()"#, "1000,10.01,65535,170,63,10000000000"),
    (r#"var r = []; for (var src of ['1__0', '1_', '0_1', '1._5', '1e_5', '0x_1']) { try { eval(src); r.push('ok') } catch (e) { r.push(e.name) } } r.join()"#, "SyntaxError,SyntaxError,SyntaxError,SyntaxError,SyntaxError,SyntaxError"),
];
